use rig::agent::{AgentHook, DispatchAction, DispatchEvent, HookContext};


struct ToolAudit;


impl AgentHook for ToolAudit {
    async fn on_dispatch(&self, _ctx: &HookContext, event: DispatchEvent<'_>) -> DispatchAction {
        // `on_dispatch` fires for model calls too; only log tool calls.
        if let (Some(name), Some(args)) = (event.tool_name(), event.tool_args()) {
            println!("calling {name} with {args}");
        }
        DispatchAction::proceed()
    }
}


// Every run of this agent is audited...
let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
    .add_hook(ToolAudit)
    .build();


// ...and this one run gets an extra hook on top.
let response = agent
    .prompt("Check the account balance, then summarize it.")
    .max_turns(3)
    .add_hook(ToolAudit)
    .await?;

use rig::agent::{AgentHook, CompletionCallAction, CompletionCallEvent, HookContext, RequestPatch};
use rig::message::ToolChoice;


struct SearchFirst;


impl AgentHook for SearchFirst {
    async fn on_completion_call(
        &self,
        ctx: &HookContext,
        _event: CompletionCallEvent<'_>,
    ) -> CompletionCallAction {
        if ctx.turn() == 1 {
            CompletionCallAction::patch(
                RequestPatch::new()
                    .active_tools(["search_web"])
                    .tool_choice(ToolChoice::Required)
                    .temperature(0.0),
            )
        } else {
            CompletionCallAction::continue_run()
        }
    }
}

use rig::agent::{AgentHook, HookContext, ModelTurnAction, ModelTurnFinished};
use rig::completion::FinishReason;


/// Ask for a shorter answer when the model ran out of output tokens, at most twice.
struct RetryTruncated;


#[derive(Clone, Default)]
struct Retries(usize);


impl AgentHook for RetryTruncated {
    async fn on_model_turn_finished(
        &self,
        ctx: &HookContext,
        event: ModelTurnFinished<'_>,
    ) -> ModelTurnAction {
        if event.finish_reason != Some(&FinishReason::Length) {
            return ModelTurnAction::continue_run();
        }
        let attempt = ctx.scratchpad().update(|retries: &mut Retries| {
            retries.0 += 1;
            retries.0
        });
        if attempt > 2 {
            return ModelTurnAction::stop("response kept getting truncated");
        }
        ModelTurnAction::retry_with_feedback("That was cut off. Answer again, more briefly.")
    }
}

use rig::agent::{AgentHook, DispatchAction, DispatchEvent, HookContext};


struct TransferPolicy {
    max_auto_transfer: u64,
}


impl AgentHook for TransferPolicy {
    async fn on_dispatch(&self, _ctx: &HookContext, event: DispatchEvent<'_>) -> DispatchAction {
        let (Some(tool_name), Some(args)) = (event.tool_name(), event.tool_args()) else {
            return DispatchAction::proceed(); // not a tool call
        };
        if tool_name != "transfer_funds" {
            return DispatchAction::proceed();
        }


        let amount = serde_json::from_str::<serde_json::Value>(args)
            .ok()
            .and_then(|v| v.get("amount").and_then(|a| a.as_u64()));


        match amount {
            Some(n) if n <= self.max_auto_transfer => DispatchAction::proceed(),
            Some(n) => DispatchAction::skip(format!(
                "denied by policy: ${n} exceeds the ${} automatic transfer limit",
                self.max_auto_transfer
            )),
            None => DispatchAction::skip("denied by policy: missing transfer amount"),
        }
    }
}

use rig::agent::{AgentHook, HookContext, OutcomeAction, OutcomeEvent};


struct TruncateResults;


impl AgentHook for TruncateResults {
    async fn on_outcome(&self, _ctx: &HookContext, event: OutcomeEvent<'_>) -> OutcomeAction {
        let Some(result) = event.tool_result() else {
            return OutcomeAction::proceed(); // a model response, or a failed call
        };
        let text = result.output().render();
        if text.len() <= 4_000 {
            return OutcomeAction::proceed();
        }
        let cut = text.char_indices().nth(4_000).map_or(text.len(), |(i, _)| i);
        OutcomeAction::rewrite_tool_result(&event, format!("{}… [truncated]", &text[..cut]))
    }
}

use rig::agent::{
    AgentHook, HookContext, InvalidToolCallAction, InvalidToolCallContext, InvalidToolCallReason,
};


struct RepairDefaultApi;


impl AgentHook for RepairDefaultApi {
    async fn on_invalid_tool_call(
        &self,
        _ctx: &HookContext,
        event: &InvalidToolCallContext,
    ) -> Option<InvalidToolCallAction> {
        match event.reason {
            InvalidToolCallReason::UnknownTool if event.tool_name == "default_api" => {
                Some(InvalidToolCallAction::repair("search_web"))
            }
            InvalidToolCallReason::UnknownTool => Some(InvalidToolCallAction::retry(format!(
                "Use one of these tools: {:?}",
                event.available_tools
            ))),
            _ => None,
        }
    }
}

use rig::agent::{AgentHook, DispatchAction, DispatchEvent, HookContext, StepEventKind};


struct ToolOnlyHook;


impl AgentHook for ToolOnlyHook {
    fn observes(&self, kind: StepEventKind) -> bool {
        matches!(kind, StepEventKind::ToolDispatch)
    }


    async fn on_dispatch(&self, _ctx: &HookContext, event: DispatchEvent<'_>) -> DispatchAction {
        if let Some(name) = event.tool_name() {
            println!("tool: {name}");
        }
        DispatchAction::proceed()
    }
}
